-- Réplica de prueba del esquema Arnold V2 (tablas, checks, llaves, RLS y funciones reales),
-- reconstruida desde information_schema/pg_policies del proyecto. Solo para pruebas locales:
-- NO ejecutar en Supabase. Las funciones private.* son aproximaciones (su código no se exportó).
do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then create role anon nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then create role authenticated nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'service_role') then create role service_role nologin bypassrls; end if;
end $$;
create schema auth; create schema private;
create table auth.users (id uuid primary key, email text, email_confirmed_at timestamptz, raw_app_meta_data jsonb default '{}');
create function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb $$;
create function auth.uid() returns uuid language sql stable as $$ select nullif(auth.jwt() ->> 'sub', '')::uuid $$;
grant usage on schema auth, private, public to anon, authenticated, service_role;

create function private.fc_role() returns text language sql stable security definer set search_path = '' as $$
  select coalesce((select u.raw_app_meta_data ->> 'role' from auth.users u where u.id = auth.uid()), 'patient') $$;
create function private.fc_is_admin() returns boolean language sql stable security definer set search_path = '' as $$ select private.fc_role() = 'admin' $$;
create function private.fc_is_staff() returns boolean language sql stable security definer set search_path = '' as $$ select private.fc_role() in ('trainer', 'admin') $$;

create table public.fc_profiles (user_id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role text not null check (role in ('patient','trainer','admin')), phone text, avatar_url text, experience_level text not null default 'beginner', preferred_units text not null default 'kg', onboarding_complete boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.fc_clients (id bigint generated by default as identity primary key, user_id uuid unique references auth.users(id), primary_trainer_id uuid not null references auth.users(id), full_name text not null check (length(trim(full_name)) between 2 and 120), email text, phone text,
  status text not null check (status in ('invited','active','paused','archived')), goal text, height_cm numeric check (height_cm is null or height_cm between 50 and 280), birth_date date, notes text, archived_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  check ((status = 'archived' and archived_at is not null) or (status <> 'archived' and archived_at is null)), check (user_id is null or user_id <> primary_trainer_id));
create table public.fc_client_staff (client_id bigint not null references fc_clients(id), staff_user_id uuid not null references auth.users(id), access_level text not null check (access_level in ('coach','viewer')), assigned_by uuid not null references auth.users(id), created_at timestamptz not null default now(), primary key (client_id, staff_user_id));

create function private.fc_can_access_client(p_client bigint) returns boolean language sql stable security definer set search_path = '' as $$
  select private.fc_is_admin() or exists (select 1 from public.fc_clients c where c.id = p_client and (c.primary_trainer_id = auth.uid() or c.user_id = auth.uid()
    or exists (select 1 from public.fc_client_staff s where s.client_id = c.id and s.staff_user_id = auth.uid()))) $$;
create function private.fc_can_write_client(p_client bigint) returns boolean language sql stable security definer set search_path = '' as $$
  select private.fc_is_admin() or exists (select 1 from public.fc_clients c where c.id = p_client and (c.primary_trainer_id = auth.uid()
    or exists (select 1 from public.fc_client_staff s where s.client_id = c.id and s.staff_user_id = auth.uid() and s.access_level = 'coach'))) $$;

create table public.fc_equipment (id bigint generated by default as identity primary key, slug text not null unique check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'), name text not null unique check (length(trim(name)) between 2 and 100), category text not null check (category in ('bodyweight','free_weight','machine','band','cardio','other')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.fc_exercises (id bigint generated by default as identity primary key, name text not null unique check (length(trim(name)) between 2 and 140), muscle_group text not null, secondary_muscles text[] not null default '{}', difficulty text not null check (difficulty in ('beginner','intermediate','advanced')), exercise_type text not null check (exercise_type in ('compound','isolation','cardio','mobility')), instructions text[] not null default '{}', coaching_tip text, video_url text check (video_url is null or video_url ~ '^https://'), is_active boolean not null default true, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.fc_exercise_equipment (exercise_id bigint not null references fc_exercises(id) on delete cascade, equipment_id bigint not null references fc_equipment(id) on delete restrict, primary key (exercise_id, equipment_id));

create table public.fc_routines (id bigint generated by default as identity primary key, owner_user_id uuid references auth.users(id), client_id bigint references fc_clients(id), created_by uuid not null references auth.users(id), name text not null check (length(trim(name)) between 2 and 140),
  source text not null check (source in ('manual','fito_ai','trainer')), goal text, experience_level text not null check (experience_level in ('beginner','intermediate','advanced')), training_location text not null check (training_location in ('home','gym','mixed')),
  focus_mode text not null check (focus_mode in ('balanced','focused')), priority_muscles text[] not null default '{}', session_minutes smallint not null check (session_minutes in (30,45,60,90)), preferred_time text, days_per_week smallint not null check (days_per_week between 1 and 7),
  archived_at timestamptz, is_active boolean, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (num_nonnulls(owner_user_id, client_id) = 1));
create table public.fc_routine_days (routine_id bigint not null references fc_routines(id) on delete cascade, day_of_week smallint not null check (day_of_week between 1 and 7), label text, primary key (routine_id, day_of_week));
create table public.fc_routine_exercises (id bigint generated by default as identity primary key, routine_id bigint not null references fc_routines(id) on delete cascade, exercise_id bigint not null references fc_exercises(id) on delete restrict, day_of_week smallint not null check (day_of_week between 1 and 7), order_index smallint not null check (order_index > 0),
  sets smallint not null check (sets between 1 and 20), reps_min smallint check (reps_min is null or reps_min between 1 and 200), reps_max smallint check (reps_max is null or reps_max between 1 and 200), duration_seconds integer check (duration_seconds is null or duration_seconds > 0), rest_seconds integer not null check (rest_seconds between 0 and 1800), notes text,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (routine_id, day_of_week, order_index), check (reps_min is null or reps_max is null or reps_max >= reps_min));

create function private.fc_can_read_routine(p bigint) returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.fc_routines r where r.id = p and (r.owner_user_id = auth.uid() or r.created_by = auth.uid() or (r.client_id is not null and private.fc_can_access_client(r.client_id)) or private.fc_is_admin())) $$;
create function private.fc_can_edit_routine(p bigint) returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.fc_routines r where r.id = p and (r.owner_user_id = auth.uid() or private.fc_is_admin() or (r.client_id is not null and private.fc_is_staff() and private.fc_can_write_client(r.client_id)))) $$;

create table public.fc_workout_sessions (id bigint generated by default as identity primary key, routine_id bigint not null references fc_routines(id), subject_user_id uuid references auth.users(id), client_id bigint references fc_clients(id), recorded_by uuid not null references auth.users(id),
  status text not null check (status in ('planned','in_progress','completed','skipped','cancelled')), started_at timestamptz, completed_at timestamptz, duration_seconds integer check (duration_seconds is null or duration_seconds >= 0), notes text,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (num_nonnulls(subject_user_id, client_id) = 1), check (completed_at is null or started_at is null or completed_at >= started_at));
create table public.fc_set_logs (id bigint generated by default as identity primary key, session_id bigint not null references fc_workout_sessions(id) on delete cascade, routine_exercise_id bigint not null references fc_routine_exercises(id), set_number smallint not null check (set_number between 1 and 30),
  reps_completed smallint check (reps_completed is null or reps_completed between 0 and 500), weight numeric check (weight is null or weight >= 0), weight_unit text not null check (weight_unit in ('kg','lb')), rpe numeric check (rpe is null or rpe between 1 and 10), completed_at timestamptz, notes text,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (session_id, routine_exercise_id, set_number));
create function private.fc_can_read_session(p bigint) returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.fc_workout_sessions s where s.id = p and (s.subject_user_id = auth.uid() or s.recorded_by = auth.uid() or (s.client_id is not null and private.fc_can_access_client(s.client_id)) or private.fc_is_admin())) $$;
create function private.fc_can_edit_session(p bigint) returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.fc_workout_sessions s where s.id = p and (s.subject_user_id = auth.uid() or s.recorded_by = auth.uid() or private.fc_is_admin())) $$;

create table public.fc_body_measurements (id bigint generated by default as identity primary key, subject_user_id uuid references auth.users(id), client_id bigint references fc_clients(id), recorded_by uuid not null references auth.users(id), measured_on date not null,
  weight_kg numeric check (weight_kg is null or weight_kg between 10 and 700), body_fat_percent numeric check (body_fat_percent is null or body_fat_percent between 0 and 100), muscle_mass_kg numeric check (muscle_mass_kg is null or muscle_mass_kg between 0 and 500), waist_cm numeric check (waist_cm is null or waist_cm between 20 and 400), notes text,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (num_nonnulls(subject_user_id, client_id) = 1), check (num_nonnulls(weight_kg, body_fat_percent, muscle_mass_kg, waist_cm) > 0));

create table public.fc_ai_routine_requests (id bigint generated by default as identity primary key, subject_user_id uuid references auth.users(id), client_id bigint references fc_clients(id), requested_by uuid not null references auth.users(id),
  training_location text not null check (training_location in ('home','gym','mixed')), focus_mode text not null check (focus_mode in ('balanced','focused')), priority_muscles text[] not null default '{}', session_minutes smallint not null check (session_minutes in (30,45,60,90)), preferred_time text,
  experience_level text not null check (experience_level in ('beginner','intermediate','advanced')), injury_notes text, status text not null check (status in ('pending','processing','completed','failed','cancelled')), error_message text,
  generated_routine_id bigint references fc_routines(id) on delete set null, created_at timestamptz not null default now(), completed_at timestamptz,
  check (num_nonnulls(subject_user_id, client_id) = 1), check ((status = 'completed' and completed_at is not null) or status <> 'completed'));
create table public.fc_ai_request_days (request_id bigint not null references fc_ai_routine_requests(id) on delete cascade, day_of_week smallint not null check (day_of_week between 1 and 7), primary key (request_id, day_of_week));

-- RLS (políticas reales relevantes)
do $$ declare t text; begin foreach t in array array['fc_profiles','fc_clients','fc_client_staff','fc_equipment','fc_exercises','fc_exercise_equipment','fc_routines','fc_routine_days','fc_routine_exercises','fc_workout_sessions','fc_set_logs','fc_body_measurements','fc_ai_routine_requests','fc_ai_request_days'] loop
  execute format('alter table public.%I enable row level security', t);
  execute format('grant select, insert, update, delete on public.%I to authenticated, service_role', t);
end loop; end $$;
grant usage, select on all sequences in schema public to authenticated, service_role;
create policy fc_clients_insert on fc_clients for insert to authenticated with check (private.fc_is_staff() and (primary_trainer_id = auth.uid() or private.fc_is_admin()) and (user_id is null or private.fc_is_admin()));
create policy fc_clients_select on fc_clients for select to authenticated using (private.fc_can_access_client(id));
create policy fc_clients_update on fc_clients for update to authenticated using (private.fc_is_staff() and private.fc_can_write_client(id)) with check (private.fc_is_staff() and private.fc_can_write_client(id));
create policy fc_exercises_read on fc_exercises for select to authenticated using (is_active or private.fc_is_admin());
create policy fc_exercises_admin_insert on fc_exercises for insert to authenticated with check (private.fc_is_admin());
create policy fc_equipment_read on fc_equipment for select to authenticated using (true);
create policy fc_exercise_equipment_read on fc_exercise_equipment for select to authenticated using (true);
create policy fc_routines_insert on fc_routines for insert to authenticated with check (created_by = auth.uid() and ((owner_user_id = auth.uid() and client_id is null) or (owner_user_id is null and client_id is not null and private.fc_is_staff() and private.fc_can_write_client(client_id))));
create policy fc_routines_select on fc_routines for select to authenticated using (owner_user_id = auth.uid() or created_by = auth.uid() or (client_id is not null and private.fc_can_access_client(client_id)) or private.fc_is_admin());
create policy fc_routines_update on fc_routines for update to authenticated using (owner_user_id = auth.uid() or private.fc_is_admin() or (client_id is not null and private.fc_is_staff() and private.fc_can_write_client(client_id)));
create policy fc_routine_days_insert on fc_routine_days for insert to authenticated with check (private.fc_can_edit_routine(routine_id));
create policy fc_routine_days_select on fc_routine_days for select to authenticated using (private.fc_can_read_routine(routine_id));
create policy fc_routine_exercises_insert on fc_routine_exercises for insert to authenticated with check (private.fc_can_edit_routine(routine_id));
create policy fc_routine_exercises_select on fc_routine_exercises for select to authenticated using (private.fc_can_read_routine(routine_id));
create policy fc_workout_sessions_insert on fc_workout_sessions for insert to authenticated with check (recorded_by = auth.uid() and status in ('planned','in_progress') and ((subject_user_id = auth.uid() and client_id is null) or (subject_user_id is null and client_id is not null and private.fc_can_write_client(client_id))));
create policy fc_workout_sessions_select on fc_workout_sessions for select to authenticated using (subject_user_id = auth.uid() or recorded_by = auth.uid() or (client_id is not null and private.fc_can_access_client(client_id)) or private.fc_is_admin());
create policy fc_set_logs_select on fc_set_logs for select to authenticated using (private.fc_can_read_session(session_id));
create policy fc_body_measurements_select on fc_body_measurements for select to authenticated using (subject_user_id = auth.uid() or recorded_by = auth.uid() or (client_id is not null and private.fc_can_access_client(client_id)) or private.fc_is_admin());

-- Funciones reales exportadas del proyecto
CREATE OR REPLACE FUNCTION public.fc_complete_my_workout(p_routine_id bigint, p_day_of_week smallint, p_started_at timestamp with time zone, p_completed_at timestamp with time zone, p_sets jsonb)
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
declare v_user_id uuid := (select auth.uid()); v_client_id bigint; v_session_id bigint;
begin
  if p_day_of_week not between 1 and 7 or p_completed_at < p_started_at then raise exception 'Invalid workout dates or day.' using errcode = '22023'; end if;
  if jsonb_typeof(p_sets) <> 'array' or jsonb_array_length(p_sets) = 0 then raise exception 'At least one completed set is required.' using errcode = '22023'; end if;
  select c.id into v_client_id from public.fc_clients c join public.fc_routines r on r.client_id = c.id
  where c.user_id = v_user_id and c.status = 'active' and r.id = p_routine_id and r.archived_at is null limit 1;
  if v_client_id is null then raise exception 'Routine is not assigned to this patient.' using errcode = '42501'; end if;
  if exists (select 1 from jsonb_to_recordset(p_sets) as x(routine_exercise_id bigint, set_number smallint)
    left join public.fc_routine_exercises re on re.id = x.routine_exercise_id and re.routine_id = p_routine_id and re.day_of_week = p_day_of_week
    where re.id is null or x.set_number not between 1 and 30) then raise exception 'One or more sets do not belong to this routine day.' using errcode = '22023'; end if;
  insert into public.fc_workout_sessions (routine_id, client_id, recorded_by, status, started_at, completed_at, duration_seconds, notes)
  values (p_routine_id, v_client_id, v_user_id, 'completed', p_started_at, p_completed_at, greatest(0, extract(epoch from (p_completed_at - p_started_at))::integer), 'Día ' || p_day_of_week)
  returning id into v_session_id;
  insert into public.fc_set_logs (session_id, routine_exercise_id, set_number, reps_completed, weight, weight_unit, completed_at)
  select v_session_id, x.routine_exercise_id, x.set_number, x.reps_completed, x.weight, 'kg', p_completed_at
  from jsonb_to_recordset(p_sets) as x(routine_exercise_id bigint, set_number smallint, reps_completed smallint, weight numeric);
  return v_session_id;
end; $function$;

CREATE OR REPLACE FUNCTION public.fc_create_client(p_full_name text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_goal text DEFAULT NULL::text, p_height_cm numeric DEFAULT NULL::numeric, p_birth_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text)
 RETURNS fc_clients LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
declare v_user_id uuid := (select auth.uid()); v_role text; v_client public.fc_clients;
begin
  select coalesce(u.raw_app_meta_data ->> 'role', 'patient') into v_role from auth.users u where u.id = v_user_id;
  if v_user_id is null or v_role not in ('trainer', 'admin') then raise exception 'Only authenticated trainers can create clients.' using errcode = '42501'; end if;
  insert into public.fc_clients (primary_trainer_id, full_name, email, phone, status, goal, height_cm, birth_date, notes)
  values (v_user_id, trim(p_full_name), nullif(trim(p_email), ''), nullif(trim(p_phone), ''), case when nullif(trim(p_email), '') is null then 'active' else 'invited' end, nullif(trim(p_goal), ''), p_height_cm, p_birth_date, nullif(trim(p_notes), ''))
  returning * into v_client;
  return v_client;
end; $function$;

CREATE OR REPLACE FUNCTION public.fc_record_my_body_measurement(p_measured_on date DEFAULT CURRENT_DATE, p_weight_kg numeric DEFAULT NULL::numeric, p_body_fat_percent numeric DEFAULT NULL::numeric, p_muscle_mass_kg numeric DEFAULT NULL::numeric, p_waist_cm numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text)
 RETURNS fc_body_measurements LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
declare v_user_id uuid := (select auth.uid()); v_client_id bigint; v_measurement public.fc_body_measurements;
begin
  select c.id into v_client_id from public.fc_clients c where c.user_id = v_user_id and c.status <> 'archived' limit 1;
  if v_client_id is null then raise exception 'No active patient record is linked to this account.' using errcode = '42501'; end if;
  if num_nonnulls(p_weight_kg, p_body_fat_percent, p_muscle_mass_kg, p_waist_cm) = 0 then raise exception 'At least one body measurement is required.' using errcode = '22023'; end if;
  insert into public.fc_body_measurements (client_id, recorded_by, measured_on, weight_kg, body_fat_percent, muscle_mass_kg, waist_cm, notes)
  values (v_client_id, v_user_id, coalesce(p_measured_on, current_date), p_weight_kg, p_body_fat_percent, p_muscle_mass_kg, p_waist_cm, nullif(trim(p_notes), ''))
  returning * into v_measurement;
  return v_measurement;
end; $function$;
grant execute on all functions in schema public to authenticated;
